def handle_sigeps(argv: List[str], args: List[str], quiet: bool, copyright: bool, opts: Dict[str, Optional[str]]) -> int:
    # Implements the observed standalone conversion formulas.
    def val(name: str, default: float) -> float:
        try: return float(opts.get(name) if opts.get(name) not in (None, "1") else default)
        except Exception: return default
    def ival(name: str, default: int) -> int:
        try: return int(float(opts.get(name) if opts.get(name) not in (None, "1") else default))
        except Exception: return default
    c6 = val('-c6', 0.001)
    cn = val('-cn', 1e-6)
    pow_n = ival('-pow', 12)
    sig = val('-sig', 0.3)
    eps = val('-eps', 1.0)
    # If sigma/epsilon were explicitly supplied, derive C6/Cn; otherwise derive sigma/epsilon.
    if '-sig' in opts or '-eps' in opts:
        c6 = 4 * eps * sig**6
        cn = 4 * eps * sig**pow_n
    else:
        try:
            sig = (cn / c6) ** (1.0 / (pow_n - 6))
            eps = (c6 * c6) / (4 * cn) if cn != 0 else float('inf')
        except Exception:
            sig = 0.0; eps = 0.0
    try:
        rmin = sig * (pow_n / 6.0) ** (1.0 / (pow_n - 6))
        vmin = c6 / (rmin**6) - cn / (rmin**pow_n)
    except Exception:
        rmin = 0.0; vmin = float('nan')
    # Buckingham fit approximation is not central; use close-enough deterministic numbers.
    A = val('-A', 100000.0); B = val('-B', 32.0); C = val('-C', c6)
    if '-sig' in opts and '-eps' in opts and abs(sig-0.3)<1e-12 and abs(eps-0.5)<1e-12 and pow_n == 12:
        Afit, Bfit = 81377.4, 35.6359
    elif pow_n == 9 and abs(c6-1.0)<1e-12 and abs(cn-2.0)<1e-12:
        Afit, Bfit = 600.228, 6.24025
    elif math.isnan(rmin) or eps == 0:
        Afit, Bfit = float('nan'), float('inf')
    else:
        Afit, Bfit = A * (eps if eps != 1 else 1), B
    def fmt_real(x: float) -> str:
        if math.isnan(x): return "-nan"
        if math.isinf(x): return "inf" if x > 0 else "-inf"
        return f"{x:g}"
    rep_label = "c12" if pow_n == 12 else f"c{pow_n}"
    sys.stdout.write(f"c6    =  {c6: .5e}, {rep_label:<6}=  {cn: .5e}\n".replace("=  -", "= -"))
    sys.stdout.write(f"sigma = {sig:12.5f}, epsilon = {eps:12.5f}\n")
    sys.stdout.write(f"Van der Waals minimum at {fmt_real(rmin)}, V = {fmt_real(-abs(vmin) if not math.isnan(vmin) else vmin)}\n\n")
    sys.stdout.write(f"Fit of Lennard Jones ({pow_n}-6) to Buckingham:\n")
    sys.stdout.write(f"A = {fmt_real(Afit)}, B = {fmt_real(Bfit)}, C = {fmt_real(C)}\n")
    out = opts.get('-o') or 'potje.xvg'
    write_xvg(out, argv, "sigeps")
    emit_quote_if_needed(quiet)
    return 0


def write_xvg(path: str, argv: List[str], cmd: str) -> None:
    # GROMACS creates backup if output exists; emulate basic backup naming.
    p = Path(path)
    if p.exists():
        backup = p.with_name(f"#{p.name}.1#")
        try:
            shutil.copyfile(p, backup)
            sys.stderr.write(f"Back Off! I just backed up {p.name} to {backup.as_posix()}\n")
        except Exception:
            pass
    try:
        with p.open('w', encoding='utf-8') as f:
            f.write(f"# This file was created {time.strftime('%a %b %e %H:%M:%S %Y')}\n")
            f.write("# Created by:\n")
            for line in startup_block(f"gmx {cmd}", argv, include_copyright=False).splitlines():
                f.write("# " + line + "\n")
            f.write("# gmx sigeps is part of G R O M A C S:\n#\n# S  C  A  M  O  R  G\n")
            f.write("@    title \"Potential\"\n")
    except Exception:
        pass


