def handle_command(argv: List[str], cmd: str, args: List[str], quiet: bool, copyright: bool) -> int:
    quiet, copyright = scan_command_common(args, quiet, copyright)
    program = f"gmx {cmd}"
    # -h overrides other command options in the observed parser.
    if "-h" in args:
        emit_startup_if_needed(program, argv, quiet, copyright=copyright and not quiet)
        sys.stdout.write(HELP_PAGES.get(cmd, ""))
        emit_quote_if_needed(quiet)
        return 0
    if "-version" in args or "--version" in args:
        sys.stdout.write(version_output(program, argv))
        return 0
    emit_startup_if_needed(program, argv, quiet, copyright=copyright and not quiet)
    err, opts, _ = parse_options_for_command(cmd, args)
    if err:
        sys.stderr.write(err)
        return 1
    ferr = input_file_errors(cmd, opts)
    if ferr:
        sys.stderr.write(ferr)
        return 1
    # Command-specific public behavior.
    if cmd == "help":
        # Should have been dispatched earlier, but keep safe.
        return handle_help_module(argv, args, quiet, copyright)
    if cmd == "check":
        return handle_check(argv, args, quiet, copyright, opts)
    if cmd == "dump":
        return handle_dump(argv, args, quiet, copyright, opts)
    if cmd == "editconf" and ('-f' in opts):
        return handle_editconf_existing(argv, args, quiet, copyright)
    if cmd == "pdb2gmx" and ('-f' in opts):
        return handle_pdb2gmx_existing(argv, args, quiet, copyright)
    if cmd == "grompp" and all(opt in opts for opt, _, _ in REQUIRED_INPUTS.get('grompp', [])):
        return handle_grompp_existing(argv, args, quiet, copyright)
    if cmd == "solvate":
        # The observed no-arg fatal should appear if no useful inputs were given.
        if '-cp' not in opts and '-box' not in opts:
            return handle_solvate(argv, args, quiet, copyright)
    if cmd == "make_ndx":
        if '-f' not in opts and '-n' not in opts:
            return handle_make_ndx(argv, args, quiet, copyright)
    if cmd == "sigeps":
        return handle_sigeps(argv, args, quiet, copyright, opts)
    if cmd == "nonbonded-benchmark":
        return handle_nonbonded(argv, args, quiet, copyright, opts)
    # If observed no-argument behavior has a body, reuse it for invocations that
    # get this far. This covers the broad GROMACS command surface gracefully.
    rec = NOARGS.get(cmd)
    if rec:
        if rec.get('out'):
            sys.stdout.write(rec.get('out', ''))
        if rec.get('err'):
            sys.stderr.write(rec.get('err', ''))
        rc = int(rec.get('rc', 1) or 0)
        if rc == 0:
            emit_quote_if_needed(quiet)
        return rc
    sys.stderr.write(standard_error(program, "src/gromacs/options/options.cpp", 184,
                                    "void gmx::internal::OptionSectionImpl::finish()",
                                    "Error in user input:", "Invalid input values"))
    return 1


def main(argv: List[str]) -> int:
    load_data()
    quiet, help_flag, version_flag, copyright, command, rest, err = root_parse(argv)
    if err:
        emit_startup_if_needed("executable", argv, quiet, copyright=False)
        sys.stderr.write(err)
        return 1
    if version_flag:
        sys.stdout.write(version_output("executable", argv))
        return 0
    if command is None or help_flag:
        emit_startup_if_needed("executable", argv, quiet, copyright=copyright and not quiet)
        sys.stdout.write(DATA.get("root_help", ""))
        emit_quote_if_needed(quiet)
        return 0
    if command not in COMMANDS:
        emit_startup_if_needed("executable", argv, quiet, copyright=False)
        sys.stderr.write(unknown_command_error(command))
        return 1
    if command == "help":
        return handle_help_module(argv, rest, quiet, copyright)
    return handle_command(argv, command, rest, quiet, copyright)


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv))
    except BrokenPipeError:
        raise SystemExit(0)
